#define MODE_HIDDEN
//#define MODE_LINEVARSIZE

#define PI 3.14159
#define blur (1./iResolution.y)

vec2 rotate(vec2 uv, float angle) {
    float cosAngle = cos(angle);
    float sinAngle = sin(angle);
    mat2 rotationMatrix = mat2(cosAngle, -sinAngle, // General rotation matrix
                               sinAngle,  cosAngle);
    return rotationMatrix * uv;
}

float swoop(vec2 uv, float lineWidth, float lineAmp) {
    float swoopY = 0.5 + 0.3 * sin(uv.x * lineAmp);
    return smoothstep(lineWidth-blur, lineWidth+blur, fract(abs(uv.y - swoopY)));
}

vec3 modC(vec3 color) {
// rg only because human eye dedicates most cones to red/green
// see https://en.wikipedia.org/wiki/Cone_cell#Types
    if (color.g >= normalize(color).g) color = vec3(0.,1.,0.);
    else color = vec3(1.,0.,0.);
    return color;
