}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Normalize the screen coordinates to the range [0, 1]
    vec2 uv0 = fragCoord / iResolution.xy;
    vec2 uv = uv0 * vec2(iResolution.x / iResolution.y, 1.);

#ifdef MODE_HIDDEN
    vec3 backgroundColor = vec3(0.1, 0.1, 0.1);
    vec3 swoopColor = texture(iChannel0, uv0).rgb;
    swoopColor = modC(swoopColor);
#else
    vec3 backgroundColor = vec3(0.1, 0.1, 0.1);
    vec3 swoopColor = vec3(0.8, 0.7, 0.9);
#endif

    // params
    float lineAmp = 10.;
    float lineAWidth = 0.2;
    float lineAScale = 5.;
    float lineBWidth = 0.1;
#ifdef MODE_LINEVARSIZE
    lineAWidth += 0.1 + 0.1*sin(iTime);
    lineBWidth += 0.1 + 0.1*sin(iTime+PI/2.);
#endif
    float lineBScale = 3.;

    vec3 color = vec3(0.);

    vec2 ruv = rotate(uv, PI/2.*3.)*lineBScale;

    uv *= lineAScale;

    color = mix(backgroundColor, swoopColor,
            (1.-swoop(uv+vec2(-iTime,1.), lineAWidth, lineAmp))
          * (1.-swoop(ruv+vec2(0.,1.+iTime), lineBWidth, lineAmp)));

    if (iMouse.z>0.1) color = swoopColor;

    // Output the final color
    fragColor = vec4(color, 1.0);
}
